from html.parser import HTMLParser
from pathlib import Path
class Check(HTMLParser):
 def __init__(self):
  super().__init__(); self.ids=set(); self.labels=[]; self.targets=[]; self.scripts=[]; self.inscript=False
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a:
   assert a['id'] not in self.ids, 'duplicate id'; self.ids.add(a['id'])
  if tag=='label' and 'for' in a: self.labels.append(a['for'])
  if tag=='a' and a.get('href','').startswith('#'): self.targets.append(a['href'][1:])
  if tag=='script': self.inscript=True
 def handle_endtag(self,tag):
  if tag=='script': self.inscript=False
 def handle_data(self,data):
  if self.inscript: self.scripts.append(data)
p=Check(); p.feed(Path('index.html').read_text())
assert all(t in p.ids for t in p.labels+p.targets)
Path('/tmp/sam-priya-script.js').write_text('\\n'.join(p.scripts))
print('HTML IDs, form labels, and anchor targets verified.')
