const fs = require('fs');
const vm = require('vm');
const assert = require('assert/strict');
function fixture(storageBlocked = false, stored = null) {
  class Element {
    constructor(id) { this.id = id; this.value = ''; this.hidden = false; this.attrs = {}; this.handlers = {}; this.children = []; this.disabled = false; this.checked = false; this.textContent = ''; }
    setAttribute(key, value) { this.attrs[key] = value; }
    removeAttribute(key) { delete this.attrs[key]; }
    addEventListener(type, handler) { this.handlers[type] = handler; }
    fire(type) { this.handlers[type]?.({ preventDefault() {} }); }
    focus() { focused = this.id; }
    replaceChildren() { this.children = []; }
    append(...children) { this.children.push(...children); }
    click() { this.fire('click'); }
    remove() {}
    get validity() { const n = Number(this.value); return {valid: this.disabled || (this.value "'!== '"'' && Number.isInteger(n) && n >= 1 && n <= 99)}; }
  }
  const ids = ['rsvp-form','guest-name','guest-count','dietary','attending-fields','decrease','increase','confirmation','name-error','attendance-error','guest-error','response-summary','confirmation-message','storage-message','edit','download'];
  const elements = Object.fromEntries(ids.map(id => [id, new Element(id)]));
  const yes = new Element('yes'); yes.value='yes';
  const no = new Element('no'); no.value='no';
  const form = elements['rsvp-form'];
  form.querySelectorAll = () => [yes,no];
  form.querySelector = selector => selector.includes(':checked') ? [yes,no].find(e => e.checked) : selector.includes('value=\"no\"') ? no : yes;
  elements['guest-count'].value = '1';
  let focused; let saved = stored; let blob;
  const document = {getElementById:id => elements[id], createElement: tag => new Element(tag), body: new Element('body')};
  const context = { document, localStorage: { getItem() { if(storageBlocked) throw Error('blocked'); return saved; }, setItem(k,v) { if(storageBlocked) throw Error('blocked'); saved=v; } }, Blob, URL: { createObjectURL(b) { blob=b; return 'blob:test'; }, revokeObjectURL() {} }, setTimeout: f => f() };
  vm.runInNewContext(fs.readFileSync('/tmp/sam-priya-script.js','utf8'), context);
  const choose = value => { yes.checked = value === 'yes'; no.checked = value === 'no'; (value==='yes'?yes:no).fire('change'); };
  return {elements, form, choose, get saved() {return saved;}, get focused() {return focused;}, get blob() {return blob;}};
}
(async () => {
  const f = fixture(); const e = f.elements;
  f.form.fire('submit'); assert.equal(f.focused,'guest-name'); assert.equal(e['name-error'].hidden,false);
  e['guest-name'].value='Alex Morgan'; f.form.fire('submit'); assert.equal(f.focused,'yes');
  f.choose('yes'); e['guest-count'].value='1.5'; f.form.fire('submit'); assert.equal(f.focused,'guest-count');
  e['guest-count'].value='1'; e.increase.click(); assert.equal(Number(e['guest-count'].value),2);
  e.dietary.value='Alex: nut allergy'; f.form.fire('submit');
  assert.equal(e.confirmation.hidden,false); assert.equal(f.form.hidden,true);
  assert.deepEqual(JSON.parse(f.saved), {name:'Alex Morgan',attending:true,guests:2,dietary:'Alex: nut allergy'});
  e.download.click(); assert.match(await f.blob.text(),/Guests \\(including respondent\\): 2/);
  e.edit.click(); assert.equal(f.form.hidden,false); assert.equal(f.focused,'guest-name');
  f.choose('no'); assert.equal(e['attending-fields'].hidden,true); assert.equal(e['guest-count'].disabled,true);
  f.form.fire('submit'); assert.equal(JSON.parse(f.saved).guests,0); assert.equal(JSON.parse(f.saved).dietary,'');
  const restored=fixture(false,f.saved); assert.equal(restored.elements['guest-name'].value,'Alex Morgan'); assert.equal(restored.elements['attending-fields'].hidden,true);
  const blocked=fixture(true); blocked.elements['guest-name'].value='Taylor'; blocked.choose('no'); blocked.form.fire('submit'); assert.match(blocked.elements['storage-message'].textContent,/couldn’t save/);
  console.log('Passed: missing name, missing attendance, invalid guest count, stepper, acceptance, decline, edit, persistence, download, and blocked-storage fallback.');
})().catch(e=>{console.error(e);process.exitCode=1});
